#include <algorithm>
#include <climits>
#include <cstdlib>
#include <functional>
#include <numeric>
#include <queue>
#include <tuple>
#include <utility>
#include <vector>

using CEdges = std::vector<std::tuple<int, int, long long>>;

namespace
{
struct UnionFind
{
    std::vector<int> parent, size;
    int sets;
    explicit UnionFind(int n) : parent(n), size(n, 1), sets(n) { std::iota(parent.begin(), parent.end(), 0); }
    int find(int x)
    {
        while (parent[x] != x) x = parent[x] = parent[parent[x]];
        return x;
    }
    bool unite(int a, int b)
    {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) std::swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        --sets;
        return true;
    }
};

void byCost(CEdges& edges)
{
    std::stable_sort(edges.begin(), edges.end(), [](const auto& x, const auto& y) { return std::get<2>(x) < std::get<2>(y); });
}
}

long long kruskal(int n, CEdges edges, std::vector<std::tuple<int, int, long long>>& chosen)
{
    byCost(edges);
    chosen.clear();
    UnionFind uf(n);
    long long total = 0;
    for (const auto& e : edges)
        if (uf.unite(std::get<0>(e), std::get<1>(e)))
        {
            chosen.push_back(e);
            total += std::get<2>(e);
        }
    return uf.sets <= 1 ? total : -1;
}

long long prim(int n, const CEdges& edges)
{
    if (n == 0) return 0;
    std::vector<std::vector<std::pair<int, long long>>> adj(n);
    for (auto [a, b, c] : edges) { adj[a].push_back({ b, c }); adj[b].push_back({ a, c }); }
    std::vector<bool> inTree(n, false);
    using Item = std::pair<long long, int>;
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
    pq.push({ 0, 0 });
    long long total = 0;
    int added = 0;
    while (!pq.empty())
    {
        auto [c, u] = pq.top();
        pq.pop();
        if (inTree[u]) continue;
        inTree[u] = true;
        total += c;
        ++added;
        for (auto [v, w] : adj[u])
            if (!inTree[v]) pq.push({ w, v });
    }
    return added == n ? total : -1;
}

long long connectPoints(const std::vector<std::pair<int, int>>& points)
{
    std::size_t n = points.size();
    if (n == 0) return 0;
    std::vector<long long> best(n, LLONG_MAX);
    std::vector<bool> inTree(n, false);
    best[0] = 0;
    long long total = 0;
    for (std::size_t step = 0; step < n; ++step)
    {
        std::size_t u = n;
        for (std::size_t i = 0; i < n; ++i)
            if (!inTree[i] && (u == n || best[i] < best[u])) u = i;
        inTree[u] = true;
        total += best[u];
        for (std::size_t v = 0; v < n; ++v)
        {
            if (inTree[v]) continue;
            long long d = std::llabs(static_cast<long long>(points[u].first) - points[v].first) +
                          std::llabs(static_cast<long long>(points[u].second) - points[v].second);
            if (d < best[v]) best[v] = d;
        }
    }
    return total;
}

std::vector<std::vector<int>> clusters(int n, CEdges edges, int k)
{
    byCost(edges);
    UnionFind uf(n);
    for (const auto& e : edges)
    {
        if (uf.sets <= k) break;
        uf.unite(std::get<0>(e), std::get<1>(e));
    }
    std::vector<std::vector<int>> groups(n);
    for (int v = 0; v < n; ++v) groups[uf.find(v)].push_back(v);
    std::vector<std::vector<int>> out;
    for (auto& g : groups)
        if (!g.empty()) out.push_back(g);                   // vertices were added in increasing order
    std::sort(out.begin(), out.end());
    return out;
}

