#include <random>

static CEdges towns() { return { { 0, 1, 7 }, { 0, 3, 5 }, { 1, 2, 8 }, { 1, 3, 9 }, { 1, 4, 7 }, { 2, 4, 5 }, { 3, 4, 15 }, { 3, 2, 6 } }; }

TEST("kruskal") {
    std::vector<std::tuple<int, int, long long>> chosen;
    CHECK_EQ(kruskal(5, towns(), chosen), 23LL);
    CHECK_EQ(chosen.size(), std::size_t{ 4 });
    CHECK(chosen[0] == std::make_tuple(0, 3, 5LL));
    CHECK(chosen[1] == std::make_tuple(2, 4, 5LL));
    CHECK(chosen[2] == std::make_tuple(3, 2, 6LL));
    CHECK(chosen[3] == std::make_tuple(0, 1, 7LL));
    CHECK_EQ(kruskal(4, { { 0, 1, 1 }, { 2, 3, 1 } }, chosen), -1LL);
    CHECK_EQ(chosen.size(), std::size_t{ 2 });
    CHECK_EQ(kruskal(1, {}, chosen), 0LL);
}
TEST("prim agrees") {
    CHECK_EQ(prim(5, towns()), 23LL);
    CHECK_EQ(prim(4, { { 0, 1, 1 }, { 2, 3, 1 } }), -1LL);
    std::mt19937 rng(4);
    CEdges e;
    for (int i = 1; i < 20000; ++i) e.push_back({ static_cast<int>(rng() % i), i, static_cast<long long>(rng() % 1000) });
    for (int k = 0; k < 60000; ++k) e.push_back({ static_cast<int>(rng() % 20000), static_cast<int>(rng() % 20000), static_cast<long long>(rng() % 1000) });
    std::vector<std::tuple<int, int, long long>> chosen;
    long long k = kruskal(20000, e, chosen);
    CHECK(k > 0);
    CHECK_EQ(prim(20000, e), k);
    CHECK_EQ(chosen.size(), std::size_t{ 19999 });
}
TEST("connecting points") {
    CHECK_EQ(connectPoints({ { 0, 0 }, { 2, 2 }, { 3, 10 }, { 5, 2 }, { 7, 0 } }), 20LL);
    CHECK_EQ(connectPoints({ { 3, 12 }, { -2, 5 }, { -4, 1 } }), 18LL);
    CHECK_EQ(connectPoints({ { 1, 1 } }), 0LL);
    std::vector<std::pair<int, int>> line;
    for (int i = 0; i < 3000; ++i) line.push_back({ (i * 7919) % 3000, 0 });   // a shuffled line of points one apart
    CHECK_EQ(connectPoints(line), 2999LL);
}
TEST("clusters") {
    CEdges e{ { 0, 1, 1 }, { 1, 2, 2 }, { 3, 4, 1 }, { 2, 3, 10 }, { 4, 5, 3 }, { 0, 5, 12 } };
    CHECK(clusters(6, e, 2) == (std::vector<std::vector<int>>{ { 0, 1, 2 }, { 3, 4, 5 } }));
    CHECK(clusters(6, e, 1) == (std::vector<std::vector<int>>{ { 0, 1, 2, 3, 4, 5 } }));
    CHECK(clusters(6, e, 6) == (std::vector<std::vector<int>>{ { 0 }, { 1 }, { 2 }, { 3 }, { 4 }, { 5 } }));
    CHECK(clusters(6, e, 4) == (std::vector<std::vector<int>>{ { 0, 1 }, { 2 }, { 3, 4 }, { 5 } }));
}

